package app.kivo.store;
import org.json.*;import java.io.*;import java.net.*;import java.security.*;import java.util.*;
/** Serial, cached public-data requests. Separate core/search limits; never retry in a blocked window. */
final class GithubClient {
 interface Clock{long now();}interface Transport{Reply request(String path,String token,String etag)throws Exception;}
 interface Observer{void changed(String resource,int remaining,long reset,long blockedUntil);}
 static final class Reply{final int status;final String body;final Map<String,String> headers;Reply(int s,String b,Map<String,String> h){status=s;body=b;headers=new HashMap<>();for(Map.Entry<String,String> e:h.entrySet())if(e.getKey()!=null&&e.getValue()!=null)headers.put(e.getKey().toLowerCase(Locale.ROOT),e.getValue());}String header(String key){return headers.getOrDefault(key,"");}}
 static final class Failure extends IOException{final int code;final boolean limited;final long retryAt;Failure(int c,String message,boolean l,long retry){super(message);code=c;limited=l;retryAt=retry;}}
 static final class Window{int remaining=-1;long reset,until;}
 final File root;final Clock clock;final Transport transport;final Observer observer;final Map<String,Window> windows=new HashMap<>();String account="";final Set<String> rejectedPublicAccounts=new HashSet<>();
 GithubClient(File cache,Observer obs){this(cache,System::currentTimeMillis,GithubClient::request,obs);}
 GithubClient(File cache,Clock time,Transport net,Observer obs){root=cache;root.mkdirs();clock=time;transport=net;observer=obs;}
 static String resource(String path){return path.startsWith("search/")?"search":"core";}
 String identity(String token)throws Exception{return hash((token.isEmpty()?"anonymous":token).getBytes("UTF-8")).substring(0,16);}
 Window window(String bucket)throws Exception{String key=account+":"+bucket;Window w=windows.get(key);if(w==null){w=new Window();File file=new File(root,"limit-"+account+"-"+bucket+".json");try{JSONObject j=new JSONObject(read(file));w.remaining=j.optInt("remaining",-1);w.reset=j.optLong("reset");w.until=j.optLong("until");}catch(Exception ignored){}windows.put(key,w);}return w;}
 void publish(String bucket,Window w){if(observer!=null)observer.changed(bucket,w.remaining,w.reset,w.until);try{write(new File(root,"limit-"+account+"-"+bucket+".json"),new JSONObject().put("remaining",w.remaining).put("reset",w.reset).put("until",w.until).toString());}catch(Exception ignored){}}
 synchronized void report(String token){try{account=identity(token);for(String bucket:new String[]{"core","search"}){Window w=window(bucket);if(w.reset>0&&w.reset<=clock.now()){w.remaining=-1;w.until=0;}publish(bucket,w);}}catch(Exception ignored){}}
 static boolean publicRead(String path){return path.startsWith("search/repositories?")||path.matches("repos/[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+(?:/releases(?:/latest|/[0-9]+|/assets/[0-9]+)?(?:\\?[^#]*)?|/issues(?:/[0-9]+/comments)?(?:\\?[^#]*)?|/contents/\\.kivo-community\\.json)?");}
 synchronized boolean publicSessionRejected(String token){try{return !token.isEmpty()&&rejectedPublicAccounts.contains(identity(token));}catch(Exception e){return false;}}
 synchronized JSONObject getPublic(String path,String token,long ttl)throws Exception{if(token.isEmpty()||!publicRead(path))return get(path,token,ttl);String id=identity(token);if(rejectedPublicAccounts.contains(id))return get(path,"",ttl);try{return get(path,token,ttl);}catch(Failure e){if(e.code!=401)throw e;rejectedPublicAccounts.add(id);return get(path,"",ttl);}}
 synchronized JSONObject get(String path,String token,long ttl)throws Exception{
  if(!path.matches("[A-Za-z0-9_./?=&%+,:;@~!*-]+")||path.contains("..")||path.startsWith("/")||path.contains("://"))throw new IOException("Ruta de GitHub no válida.");account=identity(token);String bucket=resource(path);File file=new File(root,"response-"+account+"-"+hash(path.getBytes("UTF-8"))+".json");JSONObject cached=null;try{cached=new JSONObject(read(file));}catch(Exception ignored){}
  long now=clock.now();if(cached!=null&&now-cached.optLong("time")<ttl&&now>=cached.optLong("time"))return cached.getJSONObject("body");
  Window w=window(bucket);if(w.until>now){publish(bucket,w);throw new Failure(429,waitMessage(w.until),true,w.until);}if(w.reset>0&&w.reset<=now){w.remaining=-1;w.until=0;}
  Reply reply=transport.request(path,token,cached==null?"":cached.optString("etag"));String actual=reply.header("x-ratelimit-resource");if(actual.equals("core")||actual.equals("search")){bucket=actual;w=window(bucket);}w.remaining=number(reply.header("x-ratelimit-remaining"),w.remaining);long reset=numberLong(reply.header("x-ratelimit-reset"),0)*1000;if(reset>0)w.reset=reset;
  String lower=reply.body.toLowerCase(Locale.ROOT);boolean limited=(reply.status==429)||(reply.status==403&&(w.remaining==0||!reply.header("retry-after").isEmpty()||lower.contains("rate limit")||lower.contains("abuse detection")));
  if(limited){long retry=numberLong(reply.header("retry-after"),0)*1000;long until=retry>0?now+retry:w.remaining==0&&w.reset>now?w.reset:now+60000;w.until=Math.max(until,now+1000);publish(bucket,w);throw new Failure(reply.status,waitMessage(w.until),true,w.until);}
  if(w.remaining==0&&w.reset>now)w.until=w.reset;publish(bucket,w);
  if(reply.status==304&&cached!=null){cached.put("time",now);write(file,cached.toString());return cached.getJSONObject("body");}
  if(reply.status!=200)throw new Failure(reply.status,reply.status==401?"GitHub no aceptó la sesión. Vuelve a conectar tu cuenta.":reply.status==403?"GitHub denegó esta consulta. Revisa el acceso del repositorio.":"GitHub respondió "+reply.status,false,0);
  JSONObject data=reply.body.trim().startsWith("[")?new JSONObject().put("items",new JSONArray(reply.body)):new JSONObject(reply.body);write(file,new JSONObject().put("time",now).put("etag",reply.header("etag")).put("body",data).toString());trim();return data;
 }
 synchronized void prime(String path,String token,JSONObject body)throws Exception{String id=identity(token);write(new File(root,"response-"+id+"-"+hash(path.getBytes("UTF-8"))+".json"),new JSONObject().put("time",clock.now()).put("etag","").put("body",body).toString());}
 String waitMessage(long until){return "GitHub está en pausa hasta las "+new java.text.SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date(until))+". Puedes seguir usando el catálogo guardado y F-Droid.";}
 synchronized JSONObject mutate(String path,String token,String method,JSONObject data)throws Exception{
  if(token.isEmpty())throw new IOException("Conecta GitHub para publicar.");if(!path.matches("repos/[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+/issues(?:/[0-9]+/comments|/comments/[0-9]+)?")||path.contains("..")||!(method.equals("POST")||method.equals("PATCH")))throw new IOException("Ruta de comunidad no válida.");account=identity(token);Window w=window("core");long now=clock.now();if(w.until>now)throw new Failure(429,waitMessage(w.until),true,w.until);
  HttpURLConnection c=(HttpURLConnection)new URL("https://api.github.com/"+path).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(8000);c.setReadTimeout(15000);c.setRequestMethod(method);c.setRequestProperty("User-Agent","Kivo-Store/0.9");c.setRequestProperty("Accept","application/vnd.github+json");c.setRequestProperty("Authorization","Bearer "+token);c.setRequestProperty("Content-Type","application/json; charset=utf-8");c.setRequestProperty("X-GitHub-Api-Version","2022-11-28");c.setDoOutput(true);
  try{try(OutputStream out=c.getOutputStream()){out.write(data.toString().getBytes("UTF-8"));}int code=c.getResponseCode();w.remaining=number(c.getHeaderField("X-RateLimit-Remaining"),w.remaining);long reset=numberLong(c.getHeaderField("X-RateLimit-Reset"),0)*1000;if(reset>0)w.reset=reset;if(code==429||code==403&&(w.remaining==0||c.getHeaderField("Retry-After")!=null)){w.until=Math.max(now+60000,numberLong(c.getHeaderField("Retry-After"),60)*1000+now);publish("core",w);throw new Failure(code,waitMessage(w.until),true,w.until);}publish("core",w);if(code!=200&&code!=201)throw new IOException(code==401?"La sesión GitHub no es válida.":code==403?"La cuenta o su token no pueden escribir en la comunidad. Revisa sus permisos.":"GitHub no confirmó la publicación (HTTP "+code+"). Comprueba tu reseña antes de repetirla.");try(InputStream in=c.getInputStream()){return new JSONObject(readStream(in,1024*1024));}}finally{c.disconnect();}
 }
 static Reply request(String path,String token,String etag)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL("https://api.github.com/"+path).openConnection();c.setConnectTimeout(8000);c.setReadTimeout(12000);c.setRequestProperty("User-Agent","Kivo-Store/0.6");c.setRequestProperty("Accept","application/vnd.github+json");c.setRequestProperty("X-GitHub-Api-Version","2022-11-28");if(!token.isEmpty())c.setRequestProperty("Authorization","Bearer "+token);if(!etag.isEmpty())c.setRequestProperty("If-None-Match",etag);c.setInstanceFollowRedirects(false);try{int status=c.getResponseCode();Map<String,String> h=new HashMap<>();for(Map.Entry<String,List<String>> e:c.getHeaderFields().entrySet())if(e.getKey()!=null&&!e.getValue().isEmpty())h.put(e.getKey(),e.getValue().get(0));InputStream in=status>=400?c.getErrorStream():status==304?null:c.getInputStream();String body="";if(in!=null)try(InputStream stream=in){body=readStream(stream,4*1024*1024);}return new Reply(status,body,h);}finally{c.disconnect();}}
 static int number(String n,int fallback){try{return Integer.parseInt(n);}catch(Exception e){return fallback;}}static long numberLong(String n,long fallback){try{return Long.parseLong(n);}catch(Exception e){return fallback;}}
 static String hash(byte[] bytes)throws Exception{byte[] d=MessageDigest.getInstance("SHA-256").digest(bytes);StringBuilder b=new StringBuilder();for(byte x:d)b.append(String.format(Locale.ROOT,"%02x",x&255));return b.toString();}
 static String read(File f)throws Exception{try(InputStream in=new FileInputStream(f)){return readStream(in,5*1024*1024);}}
 static String readStream(InputStream in,int max)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1){if(out.size()+n>max)throw new IOException("Respuesta demasiado grande.");out.write(bytes,0,n);}return out.toString("UTF-8");}
 static void write(File file,String data)throws Exception{File tmp=File.createTempFile("response-",".tmp",file.getParentFile());try{try(FileOutputStream out=new FileOutputStream(tmp)){out.write(data.getBytes("UTF-8"));}if(!tmp.renameTo(file))throw new IOException("No se pudo guardar la caché.");}finally{tmp.delete();}}
 void trim(){File[] fs=root.listFiles((dir,name)->name.startsWith("response-")&&name.endsWith(".json"));if(fs==null)return;long bytes=0;for(File f:fs)bytes+=f.length();if(bytes<24L*1024*1024&&fs.length<450)return;Arrays.sort(fs,Comparator.comparingLong(File::lastModified));int count=fs.length;for(File f:fs){long n=f.length();if(f.delete()){bytes-=n;count--;}if(bytes<16L*1024*1024&&count<350)break;}}
}
